"""Golden-output regression tests for the KronosForecaster."""

import numpy as np
import pytest
from skbase.utils.dependencies import _check_estimator_deps

from sktime.datasets import load_airline
from sktime.forecasting.kronos import KronosForecaster

# Reference forecasts were generated by calling the vendored
# ``sktime.libs.kronos`` prediction pipeline directly (bypassing the wrapper)
# on the same internal OHLC input frame the forecaster builds for univariate
# input: four identical columns constructed from the series.
#
# Inference used ``torch.manual_seed(42)`` (as the forecaster's
# ``deterministic=True`` does) and the default inference parameters
# (T=1.0, top_k=0, top_p=0.9, sample_count=1).
#
# The full series is used as context: Kronos is a zero-shot pretrained model
# and fitting only stores the context, so the golden values are a snapshot
# of '(fixed parameters, fixed inputs)' with no train/test split needed.
