_KRONOS_REFERENCE_CASES = [
    pytest.param(
        "NeoQuasar/Kronos-small",
        "NeoQuasar/Kronos-Tokenizer-base",
        {
            "device": "cpu",
            "deterministic": True,
        },
        [439.15387, 432.44498, 429.62512],
        id="kronos-small-airline-seed42",
    ),
    pytest.param(
        "NeoQuasar/Kronos-mini",
        "NeoQuasar/Kronos-Tokenizer-2k",
        {
            "device": "cpu",
            "deterministic": True,
        },
        [393.13846, 407.77350, 419.77557],
        id="kronos-mini-airline-seed42",
    ),
]


pytestmark = pytest.mark.skipif(
    not _check_estimator_deps(KronosForecaster, severity="none"),
    reason="run test only if KronosForecaster soft dependencies are present",
)


@pytest.mark.parametrize(
    "model_path,tokenizer_path,forecaster_kwargs,expected_head",
    _KRONOS_REFERENCE_CASES,
)
def test_kronos_airline_predictions_match_source_reference(
    model_path, tokenizer_path, forecaster_kwargs, expected_head
):
    """Kronos predictions for airline match the vendored implementation."""
    y = load_airline()
    fh = np.arange(1, 4)

    forecaster = KronosForecaster(
        model_path=model_path,
        tokenizer_path=tokenizer_path,
        **forecaster_kwargs,
    )

    y_pred = forecaster.fit(y, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy().ravel(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )
